import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Courses = () => {
  const navigate = useNavigate();
  
  const [courses, setCourses] = useState([
    { id: 1, title: 'Full Stack Development', price: 5000 },
    { id: 2, title: 'Data Science & AI', price: 6500 },
    { id: 3, title: 'React Native Mobile Dev', price: 4000 },
    { id: 4, title: 'Python for Beginners', price: 3000 },
    { id: 5, title: 'Advanced Machine Learning', price: 7000 },
    { id: 6, title: 'Cloud Computing with AWS', price: 5500 },
    { id: 7, title: 'UI/UX Design Fundamentals', price: 3500 },
    { id: 8, title: 'Cyber Security Essentials', price: 6000 },
    { id: 9, title: 'DevOps Engineering', price: 6500 },
    { id: 10, title: 'Blockchain Development', price: 7500 },
    { id: 11, title: 'Game Development with Unity', price: 5000 },
    { id: 12, title: 'Java Spring Boot Mastery', price: 6000 },
    { id: 13, title: 'Digital Marketing Masterclass', price: 2500 },
    { id: 14, title: 'SQL & Database Management', price: 3000 },
    { id: 15, title: 'iOS App Development with Swift', price: 5500 },
    { id: 16, title: 'C++ for Competitive Programming', price: 4000 },
    { id: 17, title: 'Data Structures and Algorithms', price: 4500 },
    { id: 18, title: 'Internet of Things (IoT)', price: 6000 },
    { id: 19, title: 'Big Data Analytics', price: 6500 },
    { id: 20, title: 'Software Testing & QA Automation', price: 4000 }
  ]);

  const handleEnroll = (course) => {
    navigate('/student-details', { state: { course } });
  };

  return (
    <div className="p-8 max-w-7xl mx-auto min-h-screen bg-[#060A13] text-[#FFFFFF] font-sans selection:bg-[#00D4FF] selection:text-[#000000]">
      <h1 className="text-4xl font-bold mb-10 text-center text-transparent bg-clip-text bg-gradient-to-r from-[#00D4FF] to-[#005BFF] drop-shadow-[0_0_10px_rgba(0,212,255,0.3)]">
        Available Courses
      </h1>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {courses.map((course) => (
          <div key={course.id} className="bg-[#0A0D18]/80 backdrop-blur-md border border-[#C4D1EB]/20 hover:border-[#00D4FF] p-6 rounded-xl shadow-[0_4px_20px_rgba(0,91,255,0.1)] hover:shadow-[0_0_20px_rgba(0,212,255,0.3)] transition-all duration-300 flex flex-col justify-between group">
            <div>
              <h2 className="text-xl font-semibold mb-2 text-[#FFFFFF] group-hover:text-[#00D4FF] transition-colors">{course.title}</h2>
              <p className="text-[#C4D1EB] mb-6 font-medium">Price: <span className="text-[#00D4FF] tracking-wide">₹{course.price}</span></p>
            </div>
            <button 
              onClick={() => handleEnroll(course)}
              className="w-full bg-[#005BFF] text-[#FFFFFF] py-2.5 rounded-lg hover:bg-[#009BFF] transition-all font-semibold shadow-[0_0_10px_rgba(0,91,255,0.5)] hover:shadow-[0_0_15px_rgba(0,212,255,0.8)] border border-[#005BFF] hover:border-[#00D4FF]"
            >
              Enroll Now
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Courses;
